def parse_line(line):
    chars = []
    in_quotes = False
    for char in line:
        if char == '"':
            in_quotes = not in_quotes
        elif char == '#' and not in_quotes:
            break
        chars.append(char)
    clean = "".join(chars).strip()
    if not clean:
        return None
    key, value = clean.split("=", 1)
    return key.strip(), value.strip().strip('"')

